pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0 && b > 0);
        vm.assume(address(this).balance >= a + b);
        bool r1;
        try c.deposit{value: a}() { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.deposit{value: b}() { r2 = false; } catch { r2 = true; }
        bool r3;
        try c.withdraw(a + b) { r3 = false; } catch { r3 = true; }
        assertTrue(!r1 && !r2 && !r3);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
}
